-- ============================================
-- LUMA — Thème 12 : LONG 1/3 x4 — Une exposition immersive avec plusieurs salles thématiques
-- ============================================


update scenarios set content = '{"characters": {"guide": "le guide", "narrator": "narrateur"}, "start_node": "n1", "nodes": {"n1": {"speaker": "guide", "text": "Welcome to ''Echoes of Time'' — an immersive journey through five distinct eras. Ready to begin?", "text_fr": "Bienvenue à ''Échos du Temps'' — un voyage immersif à travers cinq époques distinctes. Prêt à commencer ?", "choices": [{"text": "Absolutely, I''ve been looking forward to this exhibit.", "text_fr": "Absolument, j''ai hâte de voir cette exposition.", "next": "n2"}, {"text": "Yes, though I''m curious what makes it ''immersive'' exactly.", "text_fr": "Oui, même si je suis curieux de savoir ce qui la rend ''immersive'' exactement.", "next": "n2b"}]}, "n2": {"speaker": "guide", "text": "Wonderful! Step through this archway into the first room: Ancient Mesopotamia.", "text_fr": "Merveilleux ! Franchissez cette arche vers la première salle : la Mésopotamie ancienne.", "choices": [{"text": "(Step through, taking in the recreated ancient marketplace.)", "text_fr": "(Franchis l''arche, en observant le marché ancien recréé.)", "next": "n3"}]}, "n2b": {"speaker": "guide", "text": "You''ll see — each room recreates the sounds, scents, and visuals of its era.", "text_fr": "Vous verrez — chaque salle recrée les sons, les odeurs et les visuels de son époque.", "choices": [{"text": "That sounds incredible. Let''s start with the first room.", "text_fr": "Ça a l''air incroyable. Commençons par la première salle.", "next": "n3"}]}, "n3": {"speaker": "narrator", "text": "(Ambient sounds of a bustling market fill the air, alongside the scent of exotic spices.)", "text_fr": "(Des sons ambiants de marché animé remplissent l''air, avec le parfum d''épices exotiques.)", "choices": [{"text": "(Examine ancient clay tablets on display.)", "text_fr": "(Examine les tablettes d''argile anciennes exposées.)", "next": "n4"}, {"text": "(Listen to a recorded story about daily life in this era.)", "text_fr": "(Écoute une histoire enregistrée sur la vie quotidienne à cette époque.)", "next": "n4b"}]}, "n4": {"speaker": "narrator", "text": "The tablets contain some of humanity''s earliest written records — trade agreements, mostly.", "text_fr": "Les tablettes contiennent certains des premiers écrits de l''humanité — des accords commerciaux, surtout.", "choices": [{"text": "Fascinating how trade shaped early civilization. Let''s move to the next room.", "text_fr": "Fascinant comment le commerce a façonné les civilisations anciennes. Passons à la salle suivante.", "next": "n5"}]}, "n4b": {"speaker": "narrator", "text": "(The recording describes a merchant''s daily routine, vivid and surprisingly relatable.)", "text_fr": "(L''enregistrement décrit la routine quotidienne d''un marchand, vivante et étonnamment proche de nous.)", "choices": [{"text": "It''s amazing how similar daily concerns were, even then. Onward!", "text_fr": "C''est incroyable à quel point les préoccupations quotidiennes étaient similaires, même à l''époque. En avant !", "next": "n5"}]}, "n5": {"speaker": "narrator", "text": "(The next room transitions to Medieval Europe, complete with castle sounds and torch-lit walls.)", "text_fr": "(La salle suivante bascule vers l''Europe médiévale, avec des sons de château et des murs éclairés aux torches.)", "choices": [{"text": "(Explore the recreated knight''s armor display.)", "text_fr": "(Explore l''armure de chevalier recréée exposée.)", "next": "n6"}, {"text": "(Read the informational panel about medieval trade routes.)", "text_fr": "(Lis le panneau informatif sur les routes commerciales médiévales.)", "next": "n6b"}]}, "n6": {"speaker": "narrator", "text": "The armor weighs nearly 25 kilograms — a testament to knights'' incredible endurance.", "text_fr": "L''armure pèse près de 25 kilogrammes — un témoignage de l''endurance incroyable des chevaliers.", "choices": [{"text": "I can''t imagine fighting in something that heavy. Let''s continue exploring.", "text_fr": "Je peux pas imaginer combattre dans quelque chose d''aussi lourd. Continuons à explorer.", "next": "n7"}]}, "n6b": {"speaker": "narrator", "text": "These routes connected distant kingdoms, spreading ideas as much as goods.", "text_fr": "Ces routes reliaient des royaumes lointains, diffusant des idées autant que des marchandises.", "choices": [{"text": "Trade really was the internet of its time, in a way. Let''s move on.", "text_fr": "Le commerce était vraiment l''internet de son époque, d''une certaine façon. Continuons.", "next": "n7"}]}, "n7": {"speaker": "narrator", "text": "(The third room shifts dramatically to Renaissance Italy, filled with art and music.)", "text_fr": "(La troisième salle bascule dramatiquement vers l''Italie de la Renaissance, remplie d''art et de musique.)", "choices": [{"text": "(Admire the recreated workshop of a Renaissance artist.)", "text_fr": "(Admire l''atelier recréé d''un artiste de la Renaissance.)", "next": "n8"}]}, "n8": {"speaker": "narrator", "text": "This workshop replica shows exactly how master painters trained their apprentices.", "text_fr": "Cette réplique d''atelier montre exactement comment les maîtres peintres formaient leurs apprentis.", "choices": [{"text": "The dedication to craft back then is really inspiring.", "text_fr": "Le dévouement à l''art à l''époque est vraiment inspirant.", "next": "n9"}]}, "n9": {"speaker": "narrator", "text": "(The fourth room transports you to the Industrial Revolution, loud with mechanical sounds.)", "text_fr": "(La quatrième salle vous transporte vers la Révolution Industrielle, bruyante de sons mécaniques.)", "choices": [{"text": "(Study the working replica of an early steam engine.)", "text_fr": "(Étudie la réplique fonctionnelle d''une première machine à vapeur.)", "next": "n10"}]}, "n10": {"speaker": "narrator", "text": "This invention alone transformed how humans understood work, distance, and time itself.", "text_fr": "Cette invention à elle seule a transformé la façon dont les humains comprenaient le travail, la distance et le temps lui-même.", "choices": [{"text": "It''s incredible how much changed in such a short period.", "text_fr": "C''est incroyable à quel point les choses ont changé en si peu de temps.", "next": "n11"}]}, "n11": {"speaker": "narrator", "text": "(The final room brings you to the present day, a mirror reflecting how far humanity has come.)", "text_fr": "(La dernière salle vous amène à l''époque actuelle, un miroir reflétant le chemin parcouru par l''humanité.)", "choices": [{"text": "(Reflect quietly on the entire journey through time.)", "text_fr": "(Réfléchis tranquillement à tout le voyage à travers le temps.)", "next": "n12"}]}, "n12": {"speaker": "guide", "text": "So, after walking through five thousand years of history — what struck you most?", "text_fr": "Alors, après avoir traversé cinq mille ans d''histoire — qu''est-ce qui vous a le plus marqué ?", "choices": [{"text": "How human struggles and creativity have remained constant across every era.", "text_fr": "Comment les luttes et la créativité humaines sont restées constantes à travers chaque époque.", "next": "end_immersed"}, {"text": "The sheer pace of change, especially compared to how slow it used to be.", "text_fr": "Le simple rythme du changement, surtout comparé à comme c''était lent avant.", "next": "end_immersed"}]}, "end_immersed": {"speaker": "guide", "text": "That''s exactly the reflection we hope this exhibit inspires. Thank you for joining us.", "text_fr": "C''est exactement la réflexion qu''on espère que cette exposition inspire. Merci de nous avoir rejoints.", "end": true, "ending_label": "Voyage immersif à travers cinq époques 🏛️⏳"}}}'::jsonb, is_playable = true
where title = 'Une exposition immersive avec plusieurs salles thématiques'
  and theme_id = (select id from scenario_themes where position = 12 and language_id = (select id from languages where code = 'en'));
